// Pixel UI skin (skin.css). Its sprites are generated by `npm run skin` from
// the Sprout Lands pack, which may not be redistributed, so they're gitignored.
// The eager glob is empty when they haven't been generated and the plain look
// stays. Kept in its own module so it loads after style.css (Vite hoists glob
// imports to the top of the importing module).
import.meta.glob('./assets/ui-sprout/index.css', { eager: true });

/** Timeline bar sprites by state index (none, sun, earth, both), or null without the pack. */
const tl = import.meta.glob('./assets/ui-sprout/tl-*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;
const urlOf = (k: string) => tl[`./assets/ui-sprout/tl-${k}.png`];
export const timelineSprites: string[] | null = ['none', 'sun', 'earth', 'both'].every((k) => urlOf(k))
  ? ['none', 'sun', 'earth', 'both'].map(urlOf)
  : null;
